  loop
    if not exists (select 1 from public.books b where b.id = r.id and b.titulo = r.titre) then
      v_absentes := v_absentes || r.id;
      continue;
    end if;
    if exists (select 1 from public.book_subjects s where s.book_id = r.id) then
      v_sautees := v_sautees + 1;   -- indexée entre-temps (ou déjà par un passage précédent)
      continue;
    end if;
    v_ord := 0;
    foreach v_slug in array r.slugs loop
      select id into v_sid from public.subjects where slug = v_slug and status = 'ativo';
      if v_sid is null then raise exception 'C7 : matière % absente ou inactive', v_slug; end if;
      v_ord := v_ord + 1;
      insert into public.book_subjects (book_id, subject_id, ord) values (r.id, v_sid, v_ord)
      on conflict do nothing;
      v_poses := v_poses + 1;
    end loop;
    v_notices := v_notices + 1;
  end loop;

  if (select count(*) from public.subjects) <> v_subjects_avant then
    raise exception 'C7 : le nombre de matières a changé (THES-4)';
  end if;
  if cardinality(v_absentes) > 0 then
    raise notice 'C7 : % notice(s) absente(s) ou retitrée(s), sautée(s) : %', cardinality(v_absentes),
      array_to_string(v_absentes[1:20], ', ') || case when cardinality(v_absentes) > 20 then ', …' else '' end;
  end if;
  raise notice 'C7 : % notices indexées (% affectations), % sautées ; couverture : % / % notices',
    v_notices, v_poses, v_sautees + cardinality(v_absentes),
    (select count(distinct book_id) from public.book_subjects), (select count(*) from public.books);
end $$;

